:root {
      --ink: #eaf6ff;
      --muted: #8da5b4;
      --faint: #4d6370;
      --bg: #07121a;
      --panel: rgba(11, 28, 39, .78);
      --panel-strong: #0c2330;
      --line: rgba(173, 212, 231, .14);
      --cyan: #55e6d5;
      --cyan-soft: rgba(85, 230, 213, .14);
      --orange: #ffb86b;
      --red: #ff6f7d;
      --green: #78e08f;
      --blue: #8ab8ff;
      --shadow: 0 26px 80px rgba(0, 0, 0, .35);
      --mono: "Cascadia Code", "SFMono-Regular", Consolas, monospace;
      --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body { margin: 0; color: var(--ink); background: var(--bg); font-family: var(--sans); overflow-x: hidden; }
    body::before {
      content: ""; position: fixed; inset: 0; pointer-events: none; z-index: -3;
      background: radial-gradient(circle at 73% 7%, rgba(34, 123, 139, .23), transparent 31rem), radial-gradient(circle at 8% 36%, rgba(16, 59, 76, .34), transparent 32rem), #07121a;
    }
    body::after { content: ""; position: fixed; inset: 0; pointer-events: none; opacity: .05; z-index: 20; background-image: linear-gradient(rgba(255,255,255,.5) 1px, transparent 1px); background-size: 100% 4px; mix-blend-mode: overlay; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }
    .mono { font-family: var(--mono); }
    .topbar { height: 76px; display: flex; align-items: center; justify-content: space-between; padding: 0 clamp(20px, 5vw, 80px); border-bottom: 1px solid var(--line); position: sticky; top: 0; z-index: 10; background: rgba(7,18,26,.76); backdrop-filter: blur(18px); }
    .brand { display: flex; gap: 12px; align-items: center; letter-spacing: .14em; font: 700 14px var(--mono); }
    .brand-mark { width: 32px; height: 32px; border: 1px solid var(--cyan); color: var(--cyan); display: grid; place-items: center; border-radius: 8px; box-shadow: 0 0 22px rgba(85,230,213,.25); }
    .brand-sub { color: var(--faint); font-size: 10px; font-weight: 500; letter-spacing: .08em; }
    nav { display: flex; gap: 25px; align-items: center; }
    nav a { color: var(--muted); font: 11px var(--mono); letter-spacing: .08em; text-transform: uppercase; transition: color .2s ease; }
    nav a:hover { color: var(--cyan); }
    .status-pill { display: flex; gap: 8px; align-items: center; color: var(--green); font: 11px var(--mono); }
    .dot { width: 7px; height: 7px; background: currentColor; border-radius: 50%; box-shadow: 0 0 11px currentColor; }
    .hero { min-height: 820px; padding: clamp(68px, 9vw, 130px) clamp(20px, 8vw, 132px) 90px; position: relative; display: grid; grid-template-columns: minmax(0, 1.06fr) minmax(360px, .94fr); align-items: center; gap: 4vw; overflow: hidden; }
    .hero::before { content: "01 / THE EXPOSURE"; position: absolute; left: clamp(20px, 8vw, 132px); top: 32px; color: var(--faint); letter-spacing: .18em; font: 10px var(--mono); }
    .eyebrow { color: var(--cyan); font: 11px var(--mono); letter-spacing: .18em; text-transform: uppercase; display: flex; gap: 10px; align-items: center; }
    .eyebrow::before { content: ""; width: 30px; height: 1px; background: currentColor; box-shadow: 0 0 10px currentColor; }
    h1 { font-size: clamp(54px, 8vw, 114px); line-height: .88; letter-spacing: -.08em; margin: 26px 0 28px; max-width: 700px; font-weight: 770; }
    h1 em { color: var(--cyan); font-style: normal; text-shadow: 0 0 30px rgba(85,230,213,.24); }
    .hero-copy { color: var(--muted); font-size: clamp(16px, 1.6vw, 20px); line-height: 1.6; max-width: 560px; }
    .hero-actions { display: flex; flex-wrap: wrap; gap: 13px; margin: 34px 0 40px; }
    .btn { border: 1px solid var(--line); background: rgba(255,255,255,.04); border-radius: 7px; color: var(--ink); padding: 14px 18px; cursor: pointer; font: 700 11px var(--mono); letter-spacing: .11em; text-transform: uppercase; transition: transform .2s ease, background .2s ease, border-color .2s ease, box-shadow .2s ease; }
    .btn:hover { transform: translateY(-2px); border-color: rgba(85,230,213,.65); background: var(--cyan-soft); box-shadow: 0 10px 30px rgba(0,0,0,.2); }
    .btn-primary { color: #061419; background: var(--cyan); border-color: var(--cyan); box-shadow: 0 0 26px rgba(85,230,213,.17); }
    .btn-primary:hover { background: #79f2e4; color: #061419; }
    .micro-proof { display: flex; flex-wrap: wrap; gap: 18px; color: var(--faint); font: 10px var(--mono); text-transform: uppercase; letter-spacing: .08em; }
    .micro-proof span::before { content: "✓"; color: var(--cyan); margin-right: 7px; }
    .hero-scene { min-height: 560px; position: relative; border: 1px solid var(--line); background: linear-gradient(145deg, rgba(19, 47, 61, .88), rgba(6, 17, 25, .58)); border-radius: 18px; overflow: hidden; box-shadow: var(--shadow); }
    .scene-grid { position: absolute; inset: 0; opacity: .32; background-image: linear-gradient(rgba(85,230,213,.1) 1px, transparent 1px), linear-gradient(90deg, rgba(85,230,213,.1) 1px, transparent 1px); background-size: 38px 38px; transform: perspective(500px) rotateX(59deg) scale(1.6) translateY(115px); transform-origin: center bottom; }
    .scene-label { position: absolute; top: 18px; left: 20px; right: 20px; display: flex; justify-content: space-between; color: var(--faint); font: 10px var(--mono); letter-spacing: .1em; }
    .scene-label strong { color: var(--orange); font-weight: 600; }
    .scene-svg { position: absolute; inset: 50px 10px 10px; width: calc(100% - 20px); height: calc(100% - 60px); }
    .beam { position: absolute; top: 30%; left: -10%; width: 120%; height: 1px; background: linear-gradient(90deg, transparent, var(--cyan), transparent); box-shadow: 0 0 18px var(--cyan); animation: sweep 4.5s ease-in-out infinite; opacity: .7; }
    @keyframes sweep { 0%, 100% { transform: translateY(125px); opacity: 0; } 35%, 65% { opacity: .8; } 50% { transform: translateY(350px); } }
    .data-chip { position: absolute; bottom: 18px; left: 18px; background: rgba(3, 15, 22, .8); border: 1px solid var(--line); border-radius: 7px; padding: 10px 12px; font: 10px var(--mono); color: var(--muted); }
    .data-chip strong { display: block; color: var(--cyan); margin-bottom: 5px; }
    .scroll-note { position: absolute; bottom: 28px; right: clamp(20px, 8vw, 132px); color: var(--faint); font: 10px var(--mono); letter-spacing: .14em; text-transform: uppercase; writing-mode: vertical-rl; display: flex; gap: 8px; align-items: center; }
    .scroll-note::after { content: ""; width: 1px; height: 40px; background: var(--cyan); animation: pulse 1.8s infinite; }
    @keyframes pulse { 0%,100% { opacity: .25; transform: scaleY(.6); } 50% { opacity: 1; transform: scaleY(1); } }
    .band { padding: 20px clamp(20px, 8vw, 132px); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); display: flex; justify-content: space-between; align-items: center; gap: 20px; background: rgba(5, 16, 23, .56); }
    .band p { margin: 0; color: var(--muted); font: 12px var(--mono); letter-spacing: .05em; }
    .band p strong { color: var(--ink); font-weight: 600; }
    .band .line { height: 1px; flex: 1; background: linear-gradient(90deg, var(--cyan), transparent); max-width: 180px; }
    .section { padding: 120px clamp(20px, 8vw, 132px); position: relative; }
    .section-head { display: flex; align-items: end; justify-content: space-between; gap: 30px; margin-bottom: 54px; }
    .section-kicker { color: var(--faint); font: 10px var(--mono); letter-spacing: .18em; text-transform: uppercase; margin-bottom: 16px; }
    h2 { margin: 0; font-size: clamp(34px, 5vw, 65px); line-height: .98; letter-spacing: -.06em; max-width: 690px; }
    h2 span { color: var(--cyan); }
    .section-intro { color: var(--muted); max-width: 390px; line-height: 1.55; font-size: 14px; }
    .story-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
    .story-card { padding: 26px; border: 1px solid var(--line); border-radius: 12px; min-height: 260px; background: var(--panel); position: relative; overflow: hidden; transition: transform .2s ease, border-color .2s ease; }
    .story-card:hover { transform: translateY(-5px); border-color: rgba(85,230,213,.55); }
    .story-card::after { content: attr(data-num); position: absolute; right: 17px; top: 14px; color: rgba(85,230,213,.14); font: 700 56px var(--mono); }
    .story-card .icon { color: var(--cyan); font-size: 24px; margin-bottom: 44px; }
    .story-card h3 { margin: 0 0 11px; font-size: 20px; letter-spacing: -.035em; }
    .story-card p { color: var(--muted); font-size: 13px; line-height: 1.55; margin: 0; }
    .terminal-shell { border: 1px solid var(--line); border-radius: 13px; overflow: hidden; background: #061118; box-shadow: var(--shadow); }
    .terminal-head { background: #0b1c25; padding: 13px 16px; display: flex; justify-content: space-between; border-bottom: 1px solid var(--line); color: var(--muted); font: 10px var(--mono); }
    .terminal-head .lights { display: flex; gap: 6px; }
    .terminal-head .lights i { width: 8px; height: 8px; display: block; border-radius: 50%; background: var(--red); }.terminal-head .lights i:nth-child(2) { background: var(--orange); }.terminal-head .lights i:nth-child(3) { background: var(--green); }
    .terminal-body { height: 330px; overflow: hidden; padding: 20px 22px; position: relative; font: 12px/1.9 var(--mono); color: #a8c7cf; }
    .terminal-body::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(transparent 70%, rgba(6,17,24,.96)); }
    .cmd-line { white-space: nowrap; }.cmd-line .prompt { color: var(--cyan); }.cmd-line .ok { color: var(--green); }.cmd-line .warn { color: var(--orange); }.cmd-line .dim { color: var(--faint); }
    .toolkit { background: linear-gradient(180deg, rgba(9, 29, 39, .86), rgba(7,18,26,1)); }
    .tool-layout { display: grid; grid-template-columns: 250px 1fr; gap: 36px; align-items: start; }
    .tool-menu { position: sticky; top: 104px; display: grid; gap: 8px; }
    .tool-tab { text-align: left; border: 1px solid transparent; background: transparent; color: var(--muted); border-radius: 8px; padding: 13px 15px; cursor: pointer; font: 11px var(--mono); letter-spacing: .06em; transition: all .2s ease; }
    .tool-tab:hover, .tool-tab.active { color: var(--cyan); border-color: var(--line); background: var(--cyan-soft); }.tool-tab.active::before { content: "›"; margin-right: 8px; }
    .tool-tab small { display: block; margin-top: 5px; color: var(--faint); font: 10px var(--sans); letter-spacing: 0; }.tool-tab.active small { color: var(--muted); }
    .tool-panel { min-height: 620px; border: 1px solid var(--line); border-radius: 15px; padding: clamp(23px, 4vw, 42px); background: rgba(7, 20, 28, .74); position: relative; overflow: hidden; }
    .tool-panel::before { content: "TRUST / LOCAL DEMO"; position: absolute; top: 20px; right: 24px; color: var(--faint); font: 9px var(--mono); letter-spacing: .12em; }
    .tool-content { display: none; animation: rise .35s ease both; }.tool-content.active { display: block; }@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
    .tool-title { font-size: clamp(30px, 4vw, 48px); letter-spacing: -.06em; margin: 20px 0 10px; }.tool-description { color: var(--muted); line-height: 1.6; max-width: 630px; font-size: 14px; margin-bottom: 28px; }
    .scan-card { display: grid; grid-template-columns: 160px 1fr; gap: 28px; align-items: center; border: 1px solid var(--line); background: rgba(3, 13, 19, .7); border-radius: 12px; padding: 23px; margin-top: 22px; }
    .score-ring { width: 140px; height: 140px; border-radius: 50%; display: grid; place-items: center; background: conic-gradient(var(--cyan) 0deg, var(--cyan) calc(var(--score, 82) * 3.6deg), rgba(255,255,255,.08) calc(var(--score, 82) * 3.6deg)); position: relative; }
    .score-ring::before { content: ""; position: absolute; width: 108px; height: 108px; border-radius: 50%; background: var(--bg); }.score-value { z-index: 1; font: 700 35px var(--mono); }.score-value small { display: block; color: var(--faint); font: 9px var(--mono); text-align: center; letter-spacing: .12em; }
    .scan-meta h3 { margin: 0 0 7px; font-size: 22px; }.scan-meta p { color: var(--muted); font-size: 13px; line-height: 1.5; margin: 0 0 15px; }.progress { height: 7px; background: rgba(255,255,255,.08); border-radius: 99px; overflow: hidden; }.progress i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--blue)); transition: width .25s ease; border-radius: inherit; }
    .signal-list { display: grid; gap: 9px; margin-top: 22px; }.signal { display: grid; grid-template-columns: 1fr auto auto; gap: 15px; align-items: center; padding: 13px 14px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255,255,255,.025); font: 11px var(--mono); }.signal span { color: var(--muted); }.signal b { font-weight: 500; }.pass { color: var(--green); }.caution { color: var(--orange); }.risk { color: var(--red); }
    .sim-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }.sim-card { border: 1px solid var(--line); background: rgba(255,255,255,.03); border-radius: 10px; padding: 18px; }.sim-card h3 { font-size: 15px; margin: 0 0 8px; }.sim-card p { color: var(--muted); font-size: 12px; line-height: 1.5; margin: 0 0 16px; }.switch { width: 42px; height: 22px; background: #21313a; border: 0; padding: 3px; border-radius: 99px; cursor: pointer; text-align: left; }.switch i { display: block; width: 16px; height: 16px; border-radius: 50%; background: var(--muted); transition: transform .2s, background .2s; }.switch.on { background: rgba(255,111,125,.26); }.switch.on i { transform: translateX(20px); background: var(--red); }
    .wipe-box { border: 1px solid rgba(255,184,107,.26); background: rgba(255,184,107,.06); border-radius: 10px; padding: 22px; }.wipe-box h3 { margin: 0 0 10px; font-size: 19px; }.wipe-box p { color: var(--muted); font-size: 13px; line-height: 1.55; margin: 0 0 18px; }
    .about-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 60px; align-items: start; }.limits { display: grid; gap: 10px; }.limit { padding: 15px 0; border-top: 1px solid var(--line); display: grid; grid-template-columns: 25px 1fr; gap: 13px; }.limit b { color: var(--orange); font: 11px var(--mono); }.limit strong { display: block; font-size: 14px; margin-bottom: 5px; }.limit p { color: var(--muted); font-size: 12px; line-height: 1.5; margin: 0; }
    footer { padding: 28px clamp(20px, 8vw, 132px); border-top: 1px solid var(--line); display: flex; justify-content: space-between; gap: 20px; color: var(--faint); font: 10px var(--mono); letter-spacing: .06em; }
    #splash { position: fixed; inset: 0; z-index: 100; background: #061118; display: grid; place-items: center; transition: opacity .7s ease, visibility .7s ease; }.splash-inner { width: min(460px, calc(100vw - 48px)); }.splash-logo { display: flex; align-items: center; gap: 13px; font: 700 24px var(--mono); letter-spacing: .1em; }.splash-logo .brand-mark { width: 43px; height: 43px; }.splash-copy { color: var(--muted); margin: 27px 0 16px; font: 12px/1.65 var(--mono); }.splash-track { height: 3px; background: rgba(255,255,255,.1); overflow: hidden; }.splash-track i { display: block; width: 0; height: 100%; background: var(--cyan); box-shadow: 0 0 15px var(--cyan); animation: boot 2.2s cubic-bezier(.4,0,.2,1) forwards; }@keyframes boot { to { width: 100%; } }.splash-meta { display: flex; justify-content: space-between; margin-top: 13px; color: var(--faint); font: 9px var(--mono); letter-spacing: .1em; }.splash-done { opacity: 0; animation: showDone .2s 1.6s forwards; }.splash-hint { color: var(--cyan); }.splash-hidden { opacity: 0; visibility: hidden; pointer-events: none; }
    .toast { position: fixed; right: 22px; bottom: 22px; max-width: 330px; z-index: 50; padding: 14px 16px; border: 1px solid var(--line); border-left: 3px solid var(--cyan); background: #0b202b; color: var(--ink); border-radius: 7px; font: 11px/1.45 var(--mono); transform: translateY(20px); opacity: 0; pointer-events: none; transition: .3s ease; }.toast.show { transform: translateY(0); opacity: 1; }
    [data-reveal] { opacity: 0; transform: translateY(22px); transition: opacity .7s ease, transform .7s ease; } [data-reveal].in { opacity: 1; transform: none; }
    @media (max-width: 900px) { nav { display: none; }.hero { grid-template-columns: 1fr; min-height: auto; }.hero-scene { min-height: 460px; }.story-grid { grid-template-columns: 1fr; }.tool-layout { grid-template-columns: 1fr; }.tool-menu { position: static; display: flex; overflow-x: auto; padding-bottom: 4px; }.tool-tab { min-width: 185px; }.about-grid { grid-template-columns: 1fr; gap: 36px; } }
    @media (max-width: 560px) { .brand-sub, .status-pill { display: none; }.hero { padding-top: 90px; }.hero::before { left: 20px; }.hero-scene { min-height: 380px; }.scan-card { grid-template-columns: 1fr; }.score-ring { margin: 0 auto; }.sim-grid { grid-template-columns: 1fr; }.band { align-items: flex-start; flex-direction: column; }.band .line { width: 100%; }.section { padding-top: 80px; padding-bottom: 80px; } footer { flex-direction: column; } }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .001ms !important; } }
    .language-control { display: flex; align-items: center; gap: 7px; color: var(--muted); font: 10px var(--mono); letter-spacing: .04em; }
    .language-control select { appearance: none; border: 1px solid var(--line); border-radius: 6px; padding: 8px 26px 8px 9px; color: var(--ink); background: rgba(255,255,255,.05); font: 10px var(--mono); cursor: pointer; }
    .hero { display: block; min-height: 760px; padding-top: clamp(88px, 11vw, 150px); }
    .hero > [data-reveal]:first-child { position: relative; z-index: 3; max-width: 680px; padding: 34px 36px; border: 1px solid rgba(173,212,231,.16); border-radius: 18px; background: linear-gradient(135deg, rgba(6,20,29,.82), rgba(6,20,29,.43)); backdrop-filter: blur(8px); }
    .hero-scene { position: absolute; inset: 0; z-index: 0; width: 100%; min-height: 100%; border: 0; border-radius: 0; background-image: linear-gradient(90deg, rgba(5,16,23,.94) 0%, rgba(5,16,23,.72) 38%, rgba(5,16,23,.18) 78%), linear-gradient(0deg, rgba(5,16,23,.8), transparent 55%), url("data:image/png;base64,"); background-position: center, center, center 42%; background-size: cover, cover, cover; box-shadow: none; animation: heroDrift 18s ease-in-out infinite; }
    .hero-scene::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 72% 36%, transparent 0 12rem, rgba(5,16,23,.25) 36rem), linear-gradient(180deg, transparent 63%, var(--bg) 100%); pointer-events: none; }
    .scene-grid, .scene-svg { display: none; }
    .beam { z-index: 2; top: 22%; opacity: .25; }
    .scene-label { z-index: 3; top: 112px; right: clamp(20px, 8vw, 132px); left: auto; color: rgba(234,246,255,.75); }
    .scene-label strong { color: var(--cyan); }
    .data-chip { z-index: 3; bottom: 46px; left: clamp(20px, 8vw, 132px); max-width: 300px; }
    .image-caption { position: absolute; z-index: 3; right: clamp(20px, 8vw, 132px); bottom: 44px; color: rgba(234,246,255,.72); font: 10px var(--mono); letter-spacing: .07em; text-transform: uppercase; text-align: right; }
    .image-caption span { display: block; margin-top: 5px; color: var(--cyan); }
    .scroll-note { z-index: 4; }
    @keyframes heroDrift { 0%, 100% { background-position: center, center, 48% 42%; transform: scale(1.01); } 50% { background-position: center, center, 52% 45%; transform: scale(1.025); } }
    .physical-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 11px; margin-top: 22px; }
    .physical-check { display: flex; gap: 12px; align-items: flex-start; padding: 15px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,.025); cursor: pointer; transition: border-color .2s, background .2s; }
    .physical-check:hover, .physical-check:has(input:checked) { border-color: rgba(85,230,213,.55); background: var(--cyan-soft); }
    .physical-check input { accent-color: var(--cyan); margin-top: 3px; width: 16px; height: 16px; }
    .physical-check strong { display: block; font-size: 13px; margin-bottom: 5px; }.physical-check small { display: block; color: var(--muted); font-size: 11px; line-height: 1.45; }
    .physical-status { margin-top: 18px; padding: 13px 15px; border: 1px dashed rgba(85,230,213,.35); border-radius: 8px; color: var(--cyan); font: 11px var(--mono); }
    .plain-note { color: var(--muted); font-size: 12px; line-height: 1.55; margin-top: 13px; }
    @media (max-width: 900px) { .language-control { display: flex; }.hero > [data-reveal]:first-child { max-width: 620px; }.scene-label { top: 92px; }.physical-grid { grid-template-columns: 1fr; } }
    @media (max-width: 560px) { .hero > [data-reveal]:first-child { padding: 25px 20px; }.hero { min-height: 740px; }.image-caption { display: none; } }

    /* High-contrast language control */
    .language-control { color: var(--ink); font-weight: 800; }
    .language-control select {
      min-width: 118px;
      color: #f4fbff;
      background: #0b202b;
      border-color: rgba(85,230,213,.65);
      font-weight: 800;
      text-shadow: 0 0 8px rgba(85,230,213,.18);
    }
    .language-control select:hover,
    .language-control select:focus {
      color: #ffffff;
      background: #123442;
      border-color: var(--cyan);
      outline: 2px solid rgba(85,230,213,.22);
      outline-offset: 2px;
    }
    .language-control select option { color: #f4fbff; background: #0b202b; font-weight: 800; }
